// Plural forms – Intl.PluralRules categories (cs: one / few / many / other, en: one / other).
const P = {
  'new': { cs: { one: '{0} nová', few: '{0} nové', other: '{0} nových' }, en: { one: '{0} new', other: '{0} new' } },
  'offers': { cs: { one: '{0} nabídka', few: '{0} nabídky', other: '{0} nabídek' }, en: { one: '{0} offer', other: '{0} offers' } },
  'contacts': { cs: { one: '{0} kontakt', few: '{0} kontakty', other: '{0} kontaktů' }, en: { one: '{0} contact', other: '{0} contacts' } },
  'errors': { cs: { one: '{0} chyba', few: '{0} chyby', other: '{0} chyb' }, en: { one: '{0} error', other: '{0} errors' } },
};

/** "3 nové" / "5 nových" / "1 new" – count with the right plural form. */
export function n(word, count) {
  const forms = P[word][lang === 'en' ? 'en' : 'cs'];
  const cat = new Intl.PluralRules(locale()).select(count);
  return (forms[cat] ?? forms.other).replace('{0}', String(count));
}

/** UI string by key; {0}, {1}… are replaced by args. */
export function t(key, ...args) {
  const e = D[key];
  const s = e ? e[lang === 'en' ? 1 : 0] : key;
  return s.replace(/\{(\d)\}/g, (_, i) => String(args[Number(i)] ?? ''));
}

/** Apply translations to static markup: data-i18n (text), data-i18n-ph (placeholder), data-i18n-title (title). */
export function applyStatic(root = document) {
  for (const n of root.querySelectorAll('[data-i18n]')) n.textContent = t(n.dataset.i18n);
  for (const n of root.querySelectorAll('[data-i18n-ph]')) n.placeholder = t(n.dataset.i18nPh);
  for (const n of root.querySelectorAll('[data-i18n-title]')) n.title = t(n.dataset.i18nTitle);
}

