/** Salary label from formatSalary() ("od 80 000 CZK/měs") – units/prefixes only, applied to salary labels only. */
export function trSalary(s) {
  if (lang !== 'en' || typeof s !== 'string') return s;
  return s
    .replace(/^od (.*)$/, 'from $1')
    .replace(/^do (.*)$/, 'up to $1')
    .replace(/ (CZK|EUR|USD|GBP|PLN|CHF|SEK)\/měs$/, ' $1/month')
    .replace(/ (CZK|EUR|USD|GBP|PLN|CHF|SEK)\/rok$/, ' $1/year')
    .replace(/ (CZK|EUR|USD|GBP|PLN|CHF|SEK)\/hod$/, ' $1/hour')
    .replace(/ (CZK|EUR|USD|GBP|PLN|CHF|SEK)\/MD$/, ' $1/day');
}

/** Translate a server-generated (Czech) string to the current language. Never call it on scraped data. */
export function tr(s) {
  if (lang !== 'en' || typeof s !== 'string') return s;
  let out = s;
  for (const [re, rep] of TR) out = out.replace(re, rep);
  return out;
}
